const MS_LEVELS = MS_PHOTO_LEVELS;
const MS_LEVEL_COUNT = MS_LEVELS.length;

// One hex digit per pixel (0-15) — the inverse of how the photo-level
// generator encodes a quantized grid; see scripts/generate-mosaik-photo-levels.js.
function msDecodePixels(hex) {
  const grid = new Array(hex.length);
  for (let i = 0; i < hex.length; i++) grid[i] = parseInt(hex[i], 16);
  return grid;
}

function msGenerateLevel(levelIndex) {
  const level = MS_LEVELS[levelIndex];
  const [rows, cols] = level.g;
  // Real artwork: no formula to regenerate from, so the quantized pixel
  // grid is baked into the descriptor directly, along with its OWN small
  // palette.
  const grid = msDecodePixels(level.pixels);
  const paletteHex = level.palette;
  const paletteRgb = level.palette.map(msHexToRgb);
  // Identity mapping — every photo-level shade is its own singleton
  // family, so every family-aware helper below behaves as plain
  // exact-match here (real art is already quantized+blurred down to a
  // handful of flat colors; no family grouping needed on top of that).
  const colorFamily = paletteHex.map((_, i) => i);
  return {
    rows, cols, db: level.db, grid, paletteHex, paletteRgb, colorFamily, title: level.title || null,
    maxColors: msColorsInLevel(grid).length,
    maxFamilies: msFamiliesInLevel(grid, colorFamily).length,
    totalByColor: msOriginalColorTotals(grid),
    depot: level.depot || null, // {grid:[rows,cols], cells:[{r,c,dir,color,family}...]} — baked by scripts/generate-mosaik-depot.js; null until that pass has run for a level
  };
}
function msColumnsFromGrid(grid, rows, cols) {
  const columns = [];
  for (let c = 0; c < cols; c++) {
    const col = [];
    for (let r = rows - 1; r >= 0; r--) col.push(grid[r * cols + c]); // bottom-up
    columns.push(col);
  }
  return columns;
}

/* ══════════════════════════════════════════════════════════
   CORE PURE LOGIC — no DOM/globals, reused verbatim by
   scripts/generate-mosaik-levels.js and scripts/verify-mosaik-levels.js
   via the module.exports guard at the bottom of this file.
══════════════════════════════════════════════════════════ */
function msOriginalColorTotals(grid) {
  const totals = new Map();
  for (const v of grid) totals.set(v, (totals.get(v) || 0) + 1);
  return totals;
}
// Takes the LEVEL's total pixel count (grid.length), not any one color's —
// every color's bucket in a given level gets the exact same capacity back
// from this call; a color's own total only ever decides how many buckets
// it needs (see scripts/generate-mosaik-depot.js's unitsNeeded), not how
// big any single one of them is.
function msBucketCapacity(levelTotalPixels) {
  return Math.max(1, Math.ceil(levelTotalPixels / MS_TARGET_BUCKET_COUNT));
}
function msColorTotalCount(columns, color) {
  let n = 0;
  for (const col of columns) if (col.length) for (const v of col) if (v === color) n++;
  return n;
}
// How many columns CURRENTLY have this color exposed at the bottom
// (col[0]) — i.e. immediately collectible right now, as opposed to
// msColorTotalCount's "anywhere in the picture, however deeply buried."
// Used by the generator's placement strategy: picking by total supply
// alone can assign a container to a color that's completely buried under
// OTHER not-yet-collected colors, permanently starving it (and every
// other slot filled the same way) while a couple of small, unassigned
// colors quietly block all progress — a real deadlock, not just slow.
function msExposedCount(columns, color) {
  let n = 0;
  for (const col of columns) if (col.length && col[0] === color) n++;
  return n;
}
function msColorsInLevel(grid) { return [...new Set(grid)].sort((a, b) => a - b); }
// Family-aware counterparts of msColorTotalCount/msExposedCount/
// msColorsInLevel/msOriginalColorTotals above — same semantics, scoped to
// a whole FAMILY (several sibling shades) instead of one exact color.
// `colorFamily` is level.colorFamily: currently always an identity array
// (each shade its own singleton family), so these degenerate to the
// exact-color versions automatically — kept generic in case a future
// level ever groups sibling shades into a shared family.
function msFamiliesInLevel(grid, colorFamily) {
  return [...new Set(grid.map(v => colorFamily[v]))].sort((a, b) => a - b);
}
function msFamilyTotalCount(columns, family, colorFamily) {
  let n = 0;
  for (const col of columns) if (col.length) for (const v of col) if (colorFamily[v] === family) n++;
  return n;
}
// msFamilyTotalCount scoped down to what's still up for grabs: several
// containers can now collect the same family at once (see
// msOnDepotCellTap), so a NEW container mustn't be handed supply another
// active one already has reserved via its own capacity target — otherwise
// two containers' capacities could jointly promise more than the picture
// actually has left, permanently stranding the short-changed one.
function msFamilyUnclaimedCount(ms, level, family) {
  const total = msFamilyTotalCount(ms.columns, family, level.colorFamily);
  const committed = ms.containers
    .filter(c => c.family === family)
    .reduce((sum, c) => sum + Math.max(0, c.capacity - c.filled), 0);
  return Math.max(0, total - committed);
}
function msFamilyExposedCount(columns, family, colorFamily) {
  let n = 0;
  for (const col of columns) if (col.length && colorFamily[col[0]] === family) n++;
  return n;
}
function msTotalsByFamily(totalByColor, colorFamily) {
  const out = new Map();
  for (const [color, count] of totalByColor) {
    const fam = colorFamily[color];
    out.set(fam, (out.get(fam) || 0) + count);
  }
  return out;
}
function msIsCleared(columns) { return columns.every(col => col.length === 0); }

// Positional "parking-jam" gate layered on top of the belt mechanic — ports
// Parkplatz's plIsBlocked (js/parking.js) from cars to buckets: each depot
// cell is a ONE-TIME-USE physical bucket (fixed color, fixed release
// direction; several cells can share a color — a color that needs several
// placements to exhaust its picture supply just gets that many cells), and
// is blocked while any OTHER not-yet-released cell lies between it and that
// edge (same row/col, same cheap O(n) comparison, no pathfinding).
// `released` is an array (index i truthy = cell i has been sent — gone for
// good, matches a real car leaving a lot, and so can no longer block
// anything). A plain array rather than a bitmask because a level's total
// cell count (one per placement, not per color) can exceed 31.
function msIsDepotBlocked(cells, released, idx) {
  const cell = cells[idx];
  for (let j = 0; j < cells.length; j++) {
    if (j === idx || released[j]) continue;
    const o = cells[j];
    if (cell.dir === 0 && o.c === cell.c && o.r < cell.r) return true;
    if (cell.dir === 1 && o.r === cell.r && o.c > cell.c) return true;
    if (cell.dir === 2 && o.c === cell.c && o.r > cell.r) return true;
    if (cell.dir === 3 && o.r === cell.r && o.c < cell.c) return true;
  }
  return false;
}

// exp(-x²/2σ²) — a bell curve, not a hard cutoff: weight is 1 at the center
// and fades smoothly toward (but never exactly reaches) 0 at the edges, so
// "how far this container reaches" is a matter of likelihood, not a sharp
// in-or-out square window.
function msGaussianWeight(distance, sigma) {
  return Math.exp(-(distance * distance) / (2 * sigma * sigma));
}

// Advances every active container's belt position by dtMs, and — once its
// own per-container collection cooldown has elapsed — reaches into a small
// HALF-CIRCLE neighborhood around it: one `reach` radius (levels are always
// square, so it covers both axes identically) measured as true Euclidean
// distance from the container's own position. It comes out as a half-circle
// rather than a full one purely from how the two axes behave: column offset
// (`off`) runs both ways (nearby columns left/right of the container, same
// wrapping as beltPos itself), but depth (`idx`) only ever runs forward from
// each column's current frontmost remaining cell — there's no "behind the
// front" to reach into. The per-column depth bound at each offset
// (`maxDepth`) comes straight from the circle equation, off²+depth²≤reach².
// Each candidate cell is collected with probability equal to a Gaussian of
// its real distance from the container's center — see msGaussianWeight —
// rather than deterministically grabbing everything within a flat window.
// MUTATES state.columns/state.containers directly (this runs every
// animation frame; performance matters here unlike every other mini-game's
// occasional full-rebuild-on-tap model). Returns the column indices any
// pixel was actually collected from this tick (duplicates possible if more
// than one cell was pulled from the same column), for the caller's visual
// feedback (empty array in the common case where nothing rolled a hit).
// If two neighboring columns (a, b) differ in remaining height by more
// than MS_GRAVITY_SPILL_THRESHOLD, moves ONE grain from the taller column's
// top onto the shorter one's top and reports true. Called repeatedly by
// msSettleGravity's worklist below (each move can bring a pair back within
// threshold in a few grains, not one flat teleport), so a locally big
// imbalance still empties out grain by grain rather than the whole slope
// jumping flat in a single step — it just all happens within this same
// tick's settle pass rather than being deliberately spread across frames,
// since the disturbance triggering it was already small (a handful of
// collected pixels) and MS_GRAVITY_SPILL_THRESHOLD stops it well short of
// erasing the picture's original, undisturbed contours.
function msTrySpill(columns, a, b) {
  if (a < 0 || a >= columns.length || b < 0 || b >= columns.length) return false;
  if (columns[a].length - columns[b].length > MS_GRAVITY_SPILL_THRESHOLD) {
    columns[b].push(columns[a].pop());
    return true;
  }
  if (columns[b].length - columns[a].length > MS_GRAVITY_SPILL_THRESHOLD) {
    columns[a].push(columns[b].pop());
    return true;
  }
  return false;
}

// Real gravity doesn't only drop the pixels ABOVE a just-collected cell
// straight down within their own column (msColumnsFromGrid/the splice in
// msTick already does that much) — digging into an actual pile of sand
// also slumps the disturbed edge SIDEWAYS into whatever's lower next to
// it. This only ever runs starting from columns that just changed
// (collection, or an earlier spill in this same pass), so a picture's
// original, never-yet-disturbed silhouette is left alone — only areas the
// player has actually dug into ever get pulled toward their neighbors.
// Bounded by MAX_MOVES so one big disturbance can't blow a frame's time
// budget; in the vanishingly unlikely event that cap is hit, whatever
// didn't finish just stays uneven and gets picked up again whenever that
// area is disturbed next (nothing is lost, just deferred).
function msSettleGravity(columns, dirtyCols) {
  const changed = new Set();
  const queue = [...new Set(dirtyCols)];
  let moves = 0;
  const MAX_MOVES = 200;
  while (queue.length && moves < MAX_MOVES) {
    const c = queue.shift();
    for (const n of [c - 1, c + 1]) {
      if (msTrySpill(columns, c, n)) {
        changed.add(c);
        changed.add(n);
        queue.push(c, n);
        moves++;
      }
    }
  }
  return changed;
}

// `onCollect`, if given, is invoked synchronously with { colIdx, depthIdx,
// color, container } for every REAL pixel collection (never for a
// no-op/miss) — purely an optional visual side-channel (the interactive
// frame loop uses it to animate a pixel flying from the picture into its
// bucket) that doesn't change msTick's return contract at all, so the
// headless generator/verify/depot scripts (which never pass it) see
// zero behavior change.
function msTick(state, dtMs, onCollect) {
  const removedCols = [];
  const stillActive = [];
  const reach = Math.max(2, Math.floor(state.cols * MS_COLLECT_REACH_FRACTION));
  const sigma = Math.max(1, reach / 3);
  for (const c of state.containers) {
    c.beltPos = (c.beltPos + state.beltSpeedColsPerSec * dtMs / 1000) % state.cols;
    c.msSinceCollect += dtMs;
    if (c.filled < c.capacity && c.msSinceCollect >= state.collectIntervalMs) {
      const centerCol = Math.floor(c.beltPos);
      let burstCollected = 0;
      for (let off = -reach; off <= reach && c.filled < c.capacity && burstCollected < MS_MAX_COLLECT_PER_BURST; off++) {
        const maxDepth = Math.floor(Math.sqrt(Math.max(0, reach * reach - off * off)));
        const colIdx = ((centerCol + off) % state.cols + state.cols) % state.cols;
        const col = state.columns[colIdx];
        let examined = 0, idx = 0;
        while (examined <= maxDepth && idx < col.length && c.filled < c.capacity && burstCollected < MS_MAX_COLLECT_PER_BURST) {
          const isMatch = state.colorFamily[col[idx]] === c.family;
          const dist = Math.sqrt(off * off + idx * idx);
          const hit = isMatch && Math.random() < msGaussianWeight(dist, sigma);
          if (hit) {
            const color = col[idx];
            col.splice(idx, 1); // this cell leaves the stack; the rest re-renders compacted around the gap
            c.filled++;
            burstCollected++;
            removedCols.push(colIdx);
            if (onCollect) onCollect({ colIdx, depthIdx: idx, color, container: c });
          } else {
            idx++; // no shift happened, so advance past this position
          }
          examined++;
        }
      }
      c.msSinceCollect = 0;
    }
    if (c.filled < c.capacity) stillActive.push(c); // else: bucket's done, frees its slot
  }
  state.containers = stillActive;
  if (removedCols.length) {
    const settledCols = msSettleGravity(state.columns, removedCols);
    for (const c of settledCols) removedCols.push(c); // caller redraws every column that changed, whichever reason
  }
  return removedCols;
}

/* ══════════════════════════════════════════════════════════
   GAME FLOW — reads/writes G.mosaik
══════════════════════════════════════════════════════════ */
let msRafId = null;       // requestAnimationFrame handle, so the loop can be cancelled/restarted cleanly
let msLastFrameTime = null;
let msPictureCtx = null;  // native-resolution picture canvas 2D context
let msPictureImageData = null;
let msOverlayCtx = null;  // display-resolution container-sprite canvas 2D context
let msParticleCtx = null; // shared canvas spanning picture+belt, for flying-pixel collection animations
let msParticles = [];     // active flying-pixel animations: { x0,y0,x1,y1, color, container, t0, duration }

// Sends one specific depot cell — a ONE-TIME-USE bucket, not a reusable
// color selector (several cells can share a color when that color needs
// several placements to exhaust its picture supply; see
// scripts/generate-mosaik-depot.js). Tapping a cell that's already been
// sent, or one still positionally blocked, does nothing (blocked shows a
// toast). A successful send is PERMANENT — the cell never returns, exactly
// like a released Parkplatz car — so it both frees the belt slot's color
// AND (if it was blocking anything) relieves that positional pressure for
// good, not just temporarily.
function msOnDepotCellTap(cellIdx) {
  const ms = G.mosaik;
  if (ms.currentLevelIndex == null) return;
  const level = msGenerateLevel(ms.currentLevelIndex);
  if (!level.depot || cellIdx < 0 || cellIdx >= level.depot.cells.length) return;
  const released = ms.depotReleased;
  if (released[cellIdx]) return; // already sent
  if (msIsDepotBlocked(level.depot.cells, released, cellIdx)) {
    showToast("🔒 Blockiert! Erst andere Fächer freischalten.");
    return;
  }
  const color = level.depot.cells[cellIdx].color;
  const family = level.depot.cells[cellIdx].family;
  const slotsUnlocked = ms.slotsUnlocked || level.db;
  // Several containers can now collect the same family in parallel (each
  // still only ever the exact color of its own depot cell to render with,
  // but matched by family — see msTick) — no more "one bucket per color"
  // guard here.
  if (ms.containers.length >= slotsUnlocked) { showToast("🪣 Keine freie Behälter! Mehr freischalten (1 Frage) oder einen verwerfen?"); return; }
  // Remaining/capacity are scoped to the whole FAMILY's supply, not just
  // this cell's one exact shade — the bucket will collect every sibling
  // shade too, so capping it to this shade's own remainder would strand it
  // at a partial fill once its own shade runs out with siblings there.
  // Also subtracts what any OTHER currently-active same-family container
  // already has reserved (msFamilyUnclaimedCount) — otherwise two
  // simultaneous buckets could jointly promise more than the picture has.
  const remaining = msFamilyUnclaimedCount(ms, level, family);
  // Capacity is the level's uniform per-bucket amount, but on a family's
  // LAST placement less than that may actually be left in the picture —
  // cap at what's really still there, or this container could never reach
  // 100% (its target exhausts first) and would sit stuck at a partial fill
  // forever, permanently occupying its slot.
  if (remaining > 0) {
    ms.containers.push({
      color, family, capacity: Math.min(msBucketCapacity(level.grid.length), remaining),
      filled: 0, beltPos: 0, msSinceCollect: 0,
    });
  } // else: nothing left to collect (another cell of this family already finished it) — still sent, just empty
  released[cellIdx] = true;
  saveState(); // explicit — mid-level progress must survive a reload
  msRenderColorRow(level);
}

// Unlocks one more active slot, up to level.db (the generator-proven
// ceiling — never exceeded, see MS_STARTING_SLOTS_HANDICAP). Mirrors
// wsBuyExtraBottle / plBuyExtraBay exactly: costs one question.
function msBuyExtraSlot() {
  const ms = G.mosaik;
  if (ms.currentLevelIndex == null) return;
  const level = msGenerateLevel(ms.currentLevelIndex);
  const slotsUnlocked = ms.slotsUnlocked || level.db;
  if (slotsUnlocked >= level.db) {
    showToast(`Maximal ${level.db} Behälter für dieses Level!`);
    return;
  }
  if (!hasActiveQuestions()) {
    showToast("Keine aktiven Fragen! Aktiviere Kapitel unter 📚.");
    return;
  }
  askQuestions("🪣 Behälter freischalten", 1, () => {
    ms.slotsUnlocked = slotsUnlocked + 1;
    G.stats.mosaikSlotsUnlocked = (G.stats.mosaikSlotsUnlocked || 0) + 1;
    checkTrophies();
    saveState();
    msRenderColorRow(level);
    showToast("🪣 Neuer Behälterplatz freigeschaltet!");
  }, null);
}

function msOnLevelSolved() {
  G.stats.mosaikLevelsCompleted = (G.stats.mosaikLevelsCompleted || 0) + 1;
  checkTrophies();
  showToast("🧩 Mosaik gelöst!");
  saveState();
  setTimeout(msAdvanceToNextLevel, 900);
}

function msAdvanceToNextLevel() {
  const ms = G.mosaik;
  ms.playOrderPos++;
  if (ms.playOrderPos >= ms.playOrder.length) {
    const prevLast = ms.playOrder[ms.playOrder.length - 1];
    const order = shuffleArray([...Array(MS_LEVEL_COUNT).keys()]);
    if (order[0] === prevLast) [order[0], order[1]] = [order[1], order[0]];
    ms.playOrder = order;
    ms.playOrderPos = 0;
  }
  msStartLevel(ms.playOrder[ms.playOrderPos]);
}

function msStartLevel(levelIndex) {
  const ms = G.mosaik;
  const level = msGenerateLevel(levelIndex);
  ms.currentLevelIndex = levelIndex;
  ms.columns = msColumnsFromGrid(level.grid, level.rows, level.cols);
  ms.containers = [];
  ms.discardsUsed = 0;
  ms.slotsUnlocked = Math.max(1, level.db - MS_STARTING_SLOTS_HANDICAP);
  ms.depotReleased = level.depot ? new Array(level.depot.cells.length).fill(false) : [];
  saveState();
  msSetupCanvases(level);
  msRenderColorRow(level);
}

function msRestartLevel() {
  const ms = G.mosaik;
  if (ms.currentLevelIndex == null) return;
  msStartLevel(ms.currentLevelIndex);
  showToast("🔄 Level neu gestartet.");
}

function msEnsureQueueAndLevel() {
  const ms = G.mosaik;
  // A saved playOrder/currentLevelIndex can reference indices from a
  // larger, since-shrunk MS_LEVELS (e.g. the procedural levels were
  // retired) — stale indices would make msGenerateLevel below read past
  // the end of the array, so discard and requeue fresh rather than crash.
  const staleIndex = ms.playOrder.some(i => i >= MS_LEVEL_COUNT) ||
    (ms.currentLevelIndex != null && ms.currentLevelIndex >= MS_LEVEL_COUNT);
  if (!ms.playOrder.length || staleIndex) {
    ms.playOrder = shuffleArray([...Array(MS_LEVEL_COUNT).keys()]);
    ms.playOrderPos = 0;
    ms.currentLevelIndex = null;
    ms.columns = [];
  }
  if (ms.currentLevelIndex == null || !ms.columns.length) {
    msStartLevel(ms.playOrder[ms.playOrderPos]);
  } else {
    const level = msGenerateLevel(ms.currentLevelIndex);
    msSetupCanvases(level, true); // reconstruct the picture bitmap from current (already-dug) columns
    msRenderColorRow(level);
  }
  msStartLoop();
}

// Discards a currently-active container (forfeiting its partial fill),
// immediately freeing its slot for a different color. This is the belt
// game's real relief valve — a container whose color has stopped surfacing
// anywhere would otherwise hold its slot hostage forever (containers are
// never auto-evicted, per the confirmed design), so recognizing a dead
// pick and cutting losses is the actual player skill, gated the same way
// as every other mini-game's relief costs ("answer a question for X").
function msDiscardContainer(containerIndex) {
  const ms = G.mosaik;
  if (ms.currentLevelIndex == null) return;
  if (containerIndex < 0 || containerIndex >= ms.containers.length) return;
  if ((ms.discardsUsed || 0) >= MS_MAX_DISCARDS_PER_LEVEL) {
    showToast(`Maximal ${MS_MAX_DISCARDS_PER_LEVEL} Verwerfungen pro Level!`);
    return;
  }
  const level = msGenerateLevel(ms.currentLevelIndex);
  // A depot cell's release is permanent (see msOnDepotCellTap) — if this
  // container's color has no other not-yet-sent cell left, discarding it
  // would strand whatever it hasn't collected yet forever (nothing could
  // ever be sent for that color again). Refuse rather than let a player
  // soft-lock their own level.
  if (level.depot) {
    const family = ms.containers[containerIndex].family;
    const hasReinforcement = level.depot.cells.some((cell, i) => cell.family === family && !ms.depotReleased[i]);
    if (!hasReinforcement) {
      showToast("🚫 Letzter Behälter dieser Farbe — kann nicht verworfen werden!");
      return;
    }
  }
  if (!hasActiveQuestions()) {
    showToast("Keine aktiven Fragen! Aktiviere Kapitel unter 📚.");
    return;
  }
  askQuestions("🗑️ Behälter verwerfen", 1, () => {
    ms.containers.splice(containerIndex, 1);
    ms.discardsUsed = (ms.discardsUsed || 0) + 1;
    G.stats.mosaikContainersDiscarded = (G.stats.mosaikContainersDiscarded || 0) + 1;
    checkTrophies();
    saveState();
    msRenderColorRow(level);
    showToast("🗑️ Behälter verworfen — Platz frei!");
  }, null);
}

/* ══════════════════════════════════════════════════════════
   RENDERING — canvas-based (see file header for why). Two layers:
   a native-resolution picture canvas (one canvas pixel per grid cell,
   scaled up via CSS `image-rendering: pixelated`), updated incrementally
   via ImageData as pixels are collected; and a display-resolution overlay
   canvas for the handful of moving container sprites, redrawn every
   animation frame. Only the color-row / bucket-row / info text still use
   the app's usual innerHTML-rebuild convention (cheap, infrequent).
══════════════════════════════════════════════════════════ */
function msHexToRgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function msSetupCanvases(level, preserveCurrentColumns) {
  const pictureCanvas = document.getElementById("ms-grid");
  const overlayCanvas = document.getElementById("ms-overlay");
  if (!pictureCanvas || !overlayCanvas) return;
  pictureCanvas.width = level.cols;
  pictureCanvas.height = level.rows;
  msPictureCtx = pictureCanvas.getContext("2d");
  msPictureImageData = msPictureCtx.createImageData(level.cols, level.rows);

  const ms = G.mosaik;
  const columns = preserveCurrentColumns ? ms.columns : msColumnsFromGrid(level.grid, level.rows, level.cols);
  const buf = msPictureImageData.data;
  for (let c = 0; c < level.cols; c++) {
    const col = columns[c];
    for (let r = 0; r < level.rows; r++) {
      const stackIdx = level.rows - 1 - r;
      const val = stackIdx < col.length ? col[stackIdx] : null;
      const i = (r * level.cols + c) * 4;
      if (val == null) { buf[i + 3] = 0; continue; }
      const [rr, gg, bb] = level.paletteRgb[val];
      buf[i] = rr; buf[i + 1] = gg; buf[i + 2] = bb; buf[i + 3] = 255;
    }
  }
  msPictureCtx.putImageData(msPictureImageData, 0, 0);

  // Sized from its OWN belt-track element, not the picture — the belt is a
  // physically separate strip below the picture now, not an overlay
  // stacked on top of it.
  const rect = overlayCanvas.getBoundingClientRect();
  overlayCanvas.width = Math.max(1, Math.round(rect.width));
  overlayCanvas.height = Math.max(1, Math.round(rect.height));
  msOverlayCtx = overlayCanvas.getContext("2d");

  // Particle canvas spans the whole play area (picture + belt together, see
  // .ms-play-area) so a flying-pixel animation can travel between the two.
  const particleCanvas = document.getElementById("ms-particles");
  if (particleCanvas) {
    const pRect = particleCanvas.getBoundingClientRect();
    particleCanvas.width = Math.max(1, Math.round(pRect.width));
    particleCanvas.height = Math.max(1, Math.round(pRect.height));
    msParticleCtx = particleCanvas.getContext("2d");
  }
  msParticles = []; // a fresh level (or a resize-triggered re-setup) invalidates any in-flight particles' geometry
}

// Redraws one whole column from the current (already-shifted) `col` stack,
// so the remaining pixels stay compacted against the bottom — i.e. fall
// down to close the gap — instead of leaving a permanent hole where the
// collected pixel used to be. Cheap: at most `rows` cells touched, and only
// for columns a collection actually happened in this tick.
function msRedrawColumn(colIdx, col, rows, cols, paletteRgb) {
  if (!msPictureCtx || !msPictureImageData) return;
  const buf = msPictureImageData.data;
  for (let r = 0; r < rows; r++) {
    const stackIdx = rows - 1 - r;
    const i = (r * cols + colIdx) * 4;
    if (stackIdx < col.length) {
      const [rr, gg, bb] = paletteRgb[col[stackIdx]];
      buf[i] = rr; buf[i + 1] = gg; buf[i + 2] = bb; buf[i + 3] = 255;
    } else {
      buf[i + 3] = 0;
    }
  }
  msPictureCtx.putImageData(msPictureImageData, 0, 0, colIdx, 0, 1, rows);
}

function msRenderColorRow(level) {
  const ms = G.mosaik;
  const infoEl = document.getElementById("ms-level-info");
  const bucketRowEl = document.getElementById("ms-bucket-row");
  const colorRowEl = document.getElementById("ms-color-row");
  const discardStatusEl = document.getElementById("ms-discard-status");
  const buySlotBtn = document.getElementById("ms-buy-slot-btn");
  if (!colorRowEl) return;

  const slotsUnlocked = ms.slotsUnlocked || level.db;

  if (infoEl) {
    infoEl.textContent = `Level ${ms.currentLevelIndex + 1} / ${MS_LEVEL_COUNT}` + (level.title ? ` — ${level.title}` : '');
  }

  if (bucketRowEl) {
    bucketRowEl.innerHTML = Array.from({ length: level.db }, (_, i) => {
      if (i >= slotsUnlocked) return `<div class="ms-bucket-slot ms-bucket-slot--locked"></div>`;
      const c = ms.containers[i];
      if (!c) return `<div class="ms-bucket-slot ms-bucket-slot--empty"></div>`;
      const pct = Math.round((c.filled / c.capacity) * 100);
      return `<button class="ms-bucket-slot ms-bucket-slot--filled" style="background:${level.paletteHex[c.color]};" data-idx="${i}" title="Verwerfen (1 Frage)">
        <div class="ms-bucket-fill" style="height:${pct}%"></div>
        <span class="ms-bucket-label">${c.filled}/${c.capacity}</span>
      </button>`;
    }).join("");
    bucketRowEl.querySelectorAll(".ms-bucket-slot--filled").forEach(el => {
      el.onclick = () => msDiscardContainer(parseInt(el.dataset.idx, 10));
    });
  }

  colorRowEl.className = "ms-depot-grid";
  if (!level.depot) {
    colorRowEl.innerHTML = "";
  } else {
    // Fixed CSS Grid sized to the depot's own dimensions, one cell per
    // PLACEMENT (several cells can share a color) explicitly positioned at
    // its real r/c so a blocked cell's direction glyph points somewhere
    // meaningful — this is the depot/board: every not-yet-sent bucket is
    // visible with its real color from the moment it could ever be seen,
    // never hidden behind a generic swatch. A sent cell (ms.depotReleased
    // true) is gone for good, like a released Parkplatz car — simply
    // omitted, never re-rendered. Mirrors Parkplatz's own lot grid
    // (styles.css .pl-lot-grid), applied to one-time-use buckets.
    const released = ms.depotReleased || [];
    colorRowEl.style.gridTemplateColumns = `repeat(${level.depot.grid[1]}, 1fr)`;
    colorRowEl.style.gridTemplateRows = `repeat(${level.depot.grid[0]}, 1fr)`;
    colorRowEl.innerHTML = level.depot.cells.map((cell, idx) => {
      if (released[idx]) return "";
      const pos = `grid-row:${cell.r + 1};grid-column:${cell.c + 1};`;
      const bg = `background:${level.paletteHex[cell.color]};`;
      const blocked = msIsDepotBlocked(level.depot.cells, released, idx);
      // "Nothing left worth sending for" now means the family's whole
      // remaining supply is already reserved by active container(s), not
      // just "some container somewhere is already on this family" — several
      // containers can collect the same family in parallel (see
      // msOnDepotCellTap).
      const exhausted = !blocked && msFamilyUnclaimedCount(ms, level, cell.family) === 0;
      const cls = blocked ? "ms-depot-cell--blocked" : exhausted ? "ms-depot-cell--exhausted" : "ms-depot-cell--idle";
      const glyph = blocked ? MS_DIR_GLYPH[cell.dir] : "";
      return `<button class="ms-depot-cell ${cls}" style="${pos}${bg}" data-idx="${idx}" title="${blocked ? 'Blockiert' : 'Bereit'}">${glyph}</button>`;
    }).join("");
    colorRowEl.querySelectorAll(".ms-depot-cell:not([disabled])").forEach(el => {
      el.onclick = () => msOnDepotCellTap(parseInt(el.dataset.idx, 10));
    });
  }

  if (discardStatusEl) {
    discardStatusEl.textContent = `🗑️ ${ms.discardsUsed || 0}/${MS_MAX_DISCARDS_PER_LEVEL}`;
  }

  if (buySlotBtn) {
    const atCap = slotsUnlocked >= level.db;
    buySlotBtn.disabled = atCap;
    buySlotBtn.title = atCap ? "Maximal erreicht" : `Behälter freischalten (1 Frage) · ${slotsUnlocked}/${level.db}`;
    const badge = document.getElementById("ms-buy-slot-badge");
    if (badge) badge.textContent = atCap ? "✓" : `+`;
  }
}

function msDrawOverlay(level) {
  if (!msOverlayCtx) return;
  const ctx = msOverlayCtx;
  const w = ctx.canvas.width, h = ctx.canvas.height;
  ctx.clearRect(0, 0, w, h);
  const ms = G.mosaik;
  const colW = w / level.cols;
  // Sized off the belt-track's own height, not colW — colW is a tiny
  // fraction of a pixel-per-column for real-photo levels (hundreds of
  // columns wide), so capping radius against it collapsed every bucket down
  // to the 6px floor regardless of how roomy the actual belt strip was.
  const r = Math.max(16, h * 0.36);
  ms.containers.forEach(c => {
    const x = (c.beltPos + 0.5) * colW;
    const y = h / 2; // vertically centered in its own belt-track strip now, not pinned to the picture's bottom edge
    const pct = c.capacity ? Math.min(1, c.filled / c.capacity) : 0;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = level.paletteHex[c.color];
    ctx.fill();
    ctx.lineWidth = Math.max(1.5, r * 0.14);
    ctx.strokeStyle = "rgba(0,0,0,0.4)";
    ctx.stroke();
    // Fill-progress ring — how full THIS bucket is, legible at a glance
    // alongside its always-visible color.
    const ringR = r + ctx.lineWidth * 1.3;
    ctx.beginPath();
    ctx.arc(x, y, ringR, -Math.PI / 2, -Math.PI / 2 + pct * Math.PI * 2);
    ctx.lineWidth = Math.max(2, r * 0.22);
    ctx.strokeStyle = "rgba(255,255,255,0.9)";
    ctx.lineCap = "round";
    ctx.stroke();
  });
}

// Spawns one flying-pixel animation from where a cell was just collected in
// the picture to the bucket that collected it — purely cosmetic (the actual
// collection already happened synchronously in msTick; this only makes it
// VISIBLE that the pixel travelled somewhere instead of just vanishing).
// Reads live DOM rects once at spawn time (cheap — only runs per real
// collection, not per frame) to place both endpoints in the shared particle
// canvas's own coordinate space; see msDrawParticles for how the flight
// itself is animated frame to frame without any further DOM queries.
function msSpawnParticle(colIdx, depthIdx, colorIdx, container, level) {
  if (!msParticleCtx) return;
  const pictureCanvas = document.getElementById("ms-grid");
  const overlayCanvas = document.getElementById("ms-overlay");
  if (!pictureCanvas || !overlayCanvas) return;
  const pRect = msParticleCtx.canvas.getBoundingClientRect();
  const picRect = pictureCanvas.getBoundingClientRect();
  const ovRect = overlayCanvas.getBoundingClientRect();

  // depthIdx measures how deep into the column's remaining stack the
  // collected cell was (0 = frontmost, nearest the belt) — msSetupCanvases
  // renders stackIdx 0 at the picture's BOTTOM row, so a shallow depth maps
  // near the bottom edge and deeper cells map higher up, matching where the
  // picture visually still has more of itself left the deeper you dig.
  const xFrac = (colIdx + 0.5) / level.cols;
  const yFrac = Math.max(0, Math.min(1, 1 - depthIdx / level.rows));
  const x0 = (picRect.left - pRect.left) + xFrac * picRect.width;
  const y0 = (picRect.top - pRect.top) + yFrac * picRect.height;

  // Destination uses the exact same x/y math as msDrawOverlay, but only the
  // fixed parts (offset, column width, track mid-height) are captured now —
  // container.beltPos itself is read fresh each render frame in
  // msDrawParticles, so a particle keeps chasing its still-moving bucket
  // instead of flying toward a now-stale position.
  msParticles.push({
    x0, y0,
    color: level.paletteHex[colorIdx],
    container,
    overlayOffsetX: ovRect.left - pRect.left,
    destY: (ovRect.top - pRect.top) + ovRect.height / 2,
    colW: ovRect.width / level.cols,
    t0: performance.now(),
    duration: 320,
  });
}

// Redraws every in-flight particle spawned by msSpawnParticle, dropping any
// that have finished. Runs every animation frame regardless of whether a
// collection happened THIS frame (unlike msRenderColorRow/saveState, which
// only run on frames with a real collection) — a particle's flight spans
// many frames after its one spawning frame.
function msDrawParticles() {
  if (!msParticleCtx) return;
  const ctx = msParticleCtx;
  const w = ctx.canvas.width, h = ctx.canvas.height;
  ctx.clearRect(0, 0, w, h);
  if (!msParticles.length) return;
  const now = performance.now();
  msParticles = msParticles.filter(p => now - p.t0 < p.duration);
  for (const p of msParticles) {
    const t = Math.min(1, (now - p.t0) / p.duration);
    const ease = t * t; // ease-in — starts slow, accelerates into the bucket like a real drop
    const x1 = p.overlayOffsetX + (p.container.beltPos + 0.5) * p.colW;
    const x = p.x0 + (x1 - p.x0) * ease;
    const y = p.y0 + (p.destY - p.y0) * ease;
    const r = Math.max(1.5, 5 * (1 - 0.5 * t)); // shrinks slightly as it "falls in"
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.globalAlpha = Math.max(0, 1 - t * 0.3);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function msStartLoop() {
  if (msRafId != null) return; // already running
  msLastFrameTime = null;
  const frame = (t) => {
    const screenEl = document.getElementById("screen-mosaik");
    if (!screenEl || screenEl.hidden) { msRafId = null; return; } // tab switched away — stop, restarted by msEnsureQueueAndLevel on return
    const ms = G.mosaik;
    if (ms.currentLevelIndex == null) { msRafId = requestAnimationFrame(frame); return; }
    const level = msGenerateLevel(ms.currentLevelIndex);
    const dtMs = msLastFrameTime == null ? 0 : Math.min(200, t - msLastFrameTime); // clamp huge gaps (tab was backgrounded)
    msLastFrameTime = t;

    if (dtMs > 0 && ms.containers.length) {
      const tickState = { columns: ms.columns, containers: ms.containers, cols: level.cols, rows: level.rows, colorFamily: level.colorFamily, beltSpeedColsPerSec: MS_BELT_SPEED_COLS_PER_SEC, collectIntervalMs: MS_COLLECT_INTERVAL_MS };
      const removedCols = msTick(tickState, dtMs, (ev) => msSpawnParticle(ev.colIdx, ev.depthIdx, ev.color, ev.container, level));
      ms.containers = tickState.containers;
      if (removedCols.length) {
        [...new Set(removedCols)].forEach(colIdx => msRedrawColumn(colIdx, ms.columns[colIdx], level.rows, level.cols, level.paletteRgb));
        saveState();
        // Refresh on EVERY real collection, not just when a bucket completes —
        // otherwise `filled` keeps incrementing correctly underneath (confirmed
        // by direct inspection) while the bucket-row's displayed fill bar/label
        // stays visually frozen at its placement-time value the whole time,
        // which reads as a totally broken/stuck container to the player. This
        // is naturally throttled already: it only runs on frames where a
        // collection actually happened, which collectIntervalMs caps per
        // container (~90ms), not on every animation frame.
        msRenderColorRow(level);
        if (msIsCleared(ms.columns)) { msOnLevelSolved(); msRafId = requestAnimationFrame(frame); return; }
      }
    }
    msDrawOverlay(level);
    msDrawParticles();
    msRafId = requestAnimationFrame(frame);
  };
  msRafId = requestAnimationFrame(frame);
}

if (typeof window !== 'undefined') {
  window.msOnDepotCellTap = msOnDepotCellTap;
  window.msRestartLevel = msRestartLevel;
  window.msEnsureQueueAndLevel = msEnsureQueueAndLevel;
  window.msDiscardContainer = msDiscardContainer;
  window.msBuyExtraSlot = msBuyExtraSlot;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    MS_LEVELS, MS_LEVEL_COUNT, MS_MAX_DISCARDS_PER_LEVEL,
    MS_TARGET_BUCKET_COUNT, MS_BELT_SPEED_COLS_PER_SEC, MS_COLLECT_INTERVAL_MS,
    MS_COLLECT_REACH_FRACTION, MS_STARTING_SLOTS_HANDICAP,
    msGenerateLevel, msColumnsFromGrid, msOriginalColorTotals, msBucketCapacity,
    msColorTotalCount, msExposedCount, msColorsInLevel,
    msFamiliesInLevel, msFamilyTotalCount, msFamilyExposedCount, msTotalsByFamily,
    msIsCleared, msTick, msIsDepotBlocked, msSettleGravity,
  };
}
